public static void main(String args[])
{
    Scanner sc = new Scanner(System.in);
    int n = sc.nextInt();
    int k = sc.nextInt();

    int nums[] = new int[n];
    for (int i = 0; i < n; i++) {
        nums[i] = sc.nextInt();
    }
    int idx = 0;
    int cnt = 0;
    int temp = k;
    while (idx < n) {
        if (nums[idx] > temp) {
            cnt++;
            temp = k;
        }
        temp -= nums[idx];
        idx++;
    }
    if (temp < k) {
        cnt++;
    }
    System.out.println(cnt);
}
